head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setCellAllowChar]<br/>inputType=\"custom\" 인 Column 의 특정 Body Cell 에 입력 가능한 문자의 집합을 정규식의 문자클래스 형식으로 설정합니다.",
    "validation" : [
        "특정 Cell 의 inputType 속성이 'text', 'textImage', 'secret' 값이어야 동작합니다.",
        "rowIndex(필수) 파라미터로 입력 가능한 문자의 집합을 설정하려는 Body Cell 의 Row 인덱스를 설정할 수 있어야 합니다.",
        "rowIndex(필수) 파라미터의 Row 인덱스는 0 부터 시작하며 GridView 에 표시된 Row 를 기준으로 인덱스가 설정됩니다.",
        "columnInfo(필수) 파라미터로 입력 가능한 문자의 집합을 설정하려는 Body Cell 의 Column 인덱스를 설정할 수 있어야 합니다.",
        "columnInfo(필수) 파라미터의 Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "allowChar(필수) 파라미터로 정규식의 문자클래스 형식으로 입력이 가능한 문자 집합을 설정할 수 있어야 합니다.",
        "allowChar(필수) 파라미터는 정규식의 문자클래스에서 특수문자로 사용되는 ']', '-', '\\' 등의 문자는 이스케이프 처리를 하여야 합니다.",
        "allowChar(필수) 파라미터의 설정값은 정규식의 문자클래스('[...]')에 반영되어 입력이 가능한 문자를 찾는데 사용됩니다.",
        "기존 Cell 데이터에 허용되지 않는 문자가 포함되어 있으면 해당 문자는 즉시 제거되어 DataList 에 저장되어 데이터가 변경될 수 있습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] 4개 Body 컬럼 모두 inputType=custom + typeGetter(con_inputType 값), col1(인덱스 1) 은 숨김. 셀 초기값은 영문+숫자+특수문자+한글 혼합.\n[절차] (필요시) con_inputType 선택 -> Target 재생성 -> rowIndex / columnInfo / allowChar 선택 -> setCellAllowChar 실행. (변경 전 -> 변경 후 셀값이 리턴창에 출력된다)\n[확인1] 기존 데이터 중 허용 안 된 문자가 즉시 제거되어 변경 후 값에 허용 문자만 남는다.\n[확인2] 해당 셀 더블클릭(편집모드) -> 허용 안 된 문자 포함 입력 -> 포커스아웃 시 onafteredit 에서 허용 문자만 남은 표시값이 출력된다."', '', 'label1');

    // dataList 생성 + 초기값 바인딩 (allowChar 가 필터링할 셀의 원본 데이터 : 혼합 문자)
    //  ※ createBasicDataList 는 col1~col4 (4컬럼) 스키마만 생성하므로 5컬럼 이상은 데이터가 유실됨([createDynamicDataList 4col limit]).
    //  ※ Body custom 컬럼 id 가 dataList 컬럼(col1~col4)과 일치해야 셀 편집 가능(불일치 시 자동 readOnly).
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "AB12-CD", "col2": "abc123!", "col3": "한글ABC", "col4": "010-1234" },
        { "col1": "X9Y8Z7", "col2": "Hello42", "col3": "서울99", "col4": "02-555-7788" },
        { "col1": "Pw@2026", "col2": "ID-007x", "col3": "코드ZX5", "col4": "031-9090" },
        { "col1": "Q1w2-E3", "col2": "user88K", "col3": "강남GU3", "col4": "070-1004" }
    ]);

    // target 생성
    //  4개 Body 컬럼 모두 inputType=custom + typeGetter 로 Cell inputType=con_inputType(기본 text) 구성.
    //   col0(idx0) / col1(idx1, ★ setColumnVisible(1,false) 로 숨김 -> 인덱스는 1 유지) / col2(idx2) / col3(idx3)
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" id="" ev:onafteredit="scwin.target1_onafteredit" style="width:680px;height:200px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="170" inputType="text" id="hcol1" value="col0 (custom)"></w2:column>';
    strTarget += '<w2:column width="170" inputType="text" id="hcol2" value="col1 (숨김)"></w2:column>';
    strTarget += '<w2:column width="170" inputType="text" id="hcol3" value="col2 (custom)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="col3 (custom)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="170" inputType="custom" id="col1" dataList="col1" typeGetter="scwin.target1_textTypeGetter"></w2:column>';
    strTarget += '<w2:column width="170" inputType="custom" id="col2" dataList="col2" typeGetter="scwin.target1_textTypeGetter"></w2:column>';
    strTarget += '<w2:column width="170" inputType="custom" id="col3" dataList="col3" typeGetter="scwin.target1_textTypeGetter"></w2:column>';
    strTarget += '<w2:column width="*" inputType="custom" id="col4" dataList="col4" typeGetter="scwin.target1_textTypeGetter"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // ★ 두번째 Column(인덱스 1) 을 숨김 -> "숨겨진 Column 도 포함하여 인덱스가 설정" 검증용
    scwin.target1.setColumnVisible(1, false);
}



// 모든 custom 컬럼의 Cell inputType 을 con_inputType 선택값으로 구성한다.
//  @validation1 검증용 : allow-list(text/textImage/secret) 이면 setCellAllowChar 동작,
//                        그 외(textarea/number 등) 이면 "Invalid cell input type" 로 미동작(false) 됨을 확인한다.
//  ※ con_inputType 변경 후에는 'Target 재생성' 을 클릭해야 grid 가 새 inputType 으로 다시 그려진다.
scwin.target1_textTypeGetter = function (info) {
    let it = (typeof con_inputType !== 'undefined' && con_inputType.getValue()) ? con_inputType.getValue() : 'text';
    // textImage 셀은 viewType/imageSrc 가 있어야 셀에 이미지(아이콘)가 렌더된다.
    let opts = (it === 'textImage') ? { viewType: 'icon', imageSrc: '/cm/images/base/ico_grid_del.svg' } : {};
    return { id: 'cell_' + it + '_' + info.rowIndex + '_' + info.colIndex, inputType: it, options: opts };
};



// setCellAllowChar 실행 : 특정 셀에 입력 가능 문자집합(정규식 문자클래스)을 설정 (3인자, 전제 미충족 시 false)
//  실행 시 기존 셀 데이터의 허용 안 된 문자가 즉시 제거되어 DataList 에 저장됨(@spec). 변경 전/후 셀값을 출력해 확인한다.
scwin.btn_setCellAllowChar_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    let columnInfo = Number(par_columnInfo.getValue());
    let allowChar = par_allowChar.getValue();

    // 변경 전 셀 데이터(필터 적용 전 원본)
    let before = scwin.target1.getCellData(rowIndex, columnInfo);

    let ret = scwin.target1.setCellAllowChar(rowIndex, columnInfo, allowChar);

    // 변경 후 셀 데이터(허용 안 된 문자 즉시 제거됨)
    let after = scwin.target1.getCellData(rowIndex, columnInfo);

    wf_body_bottom.getObj("scwin").setReturnValue(
        "setCellAllowChar(" + rowIndex + ", " + columnInfo + ", '" + allowChar + "')"
        + (ret === false ? " 미동작(false)" : "")
        + " | 변경 전 : " + before + " -> 변경 후 : " + after);
}



// 셀 편집모드 종료(포커스아웃) 시 발생. allowChar 로 허용되지 않은 문자가 잘려 셀에 표시된 값을 리턴창에 출력한다.
//  onafteredit @param : (rowIndex, columnIndex, value) 위치 인자. 표시값은 getCellDisplayData 로 조회.
scwin.target1_onafteredit = function (rowIndex, columnIndex, value) {
    let shown = scwin.target1.getCellDisplayData(rowIndex, columnIndex);
    wf_body_bottom.getObj("scwin").setReturnValue(
        "셀(" + rowIndex + "," + columnIndex + ") 표시값 : " + shown);
}
